verus! {
    use vstd::prelude::*;

    /// Copy each element of a vector into a fresh vector.
    /// The result has the same length as `a`, and for every
    /// valid index `i`, `result[i] == a[i]`.
    pub fn copy<T: Copy>(a: &Vec<T>) -> Vec<T>
        ensures(|res: Vec<T>| 
            res.len() == a.len() &&
            forall(|i: usize| i < a.len() ==> res[i] == a[i])
        )
    {
        // We build up `res` by pushing one element at a time.
        let mut res: Vec<T> = Vec::with_capacity(a.len());
        let mut i: usize = 0;
        while i < a.len()
            invariant
                // we never go past the end of `a`
                i <= a.len(),
                // the result so far has length exactly `i`
                res.len() == i,
                // and all elements up to `i` agree with `a`
                forall(|j: usize| j < i ==> res[j] == a[j])
            decreases a.len() - i
        {
            // copy the next element
            res.push(a[i]);
            i += 1;
        }
        res
    }
}